    local function decodeBase64(data)
    	if crypt and crypt.base64decode then
    		return crypt.base64decode(data)
    	end
    	if base64_decode then
    		return base64_decode(data)
    	end
    	local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    	data = data:gsub("[^" .. b .. "=]", "")
    	return (data:gsub(".", function(x)
    		if x == "=" then return "" end
    		local r, f = "", (b:find(x) - 1)
    		for i = 6, 1, -1 do
    			r = r .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
    		end
    		return r
    	end):gsub("%d%d%d%d%d%d%d%d", function(x)
    		local c = 0
    		for i = 1, 8 do
    			c = c + (x:sub(i, i) == "1" and 2 ^ (8 - i) or 0)
    		end
    		return string.char(c)
    	end))
    end
    
    local function ensureBgFiles()
    	if not writefile then return false end
    	pcall(function()
    		if makefolder and (not isfolder or not isfolder("YuhLagger_BG")) then
    			makefolder("YuhLagger_BG")
    		end
    	end)
    	for _, path in ipairs(BG_FILES) do
    		local short = path:match("([^/]+)$")
    		local b64 = short and EMBEDDED_BG[short]
    		if b64 then
    			pcall(function()
    				writefile(path, decodeBase64(b64))
    			end)
    		end
    	end
    	return true
    end
    
    local function resolveAsset(path)
    	local tries = {}
    	if getcustomasset then
    		table.insert(tries, function(p) return getcustomasset(p) end)
    		table.insert(tries, function(p) return getcustomasset(p, true) end)
    	end
    	if getsynasset then
    		table.insert(tries, function(p) return getsynasset(p) end)
    	end
    	for _, fn in ipairs(tries) do
    		local ok, res = pcall(fn, path)
    		if ok and type(res) == "string" and #res > 0 then return res end
    	end
    	local short = path:match("([^/]+)$")
    	if short then
    		for _, fn in ipairs(tries) do
    			local ok, res = pcall(fn, short)
    			if ok and type(res) == "string" and #res > 0 then return res end
    			ok, res = pcall(fn, "YuhLagger_BG/" .. short)
    			if ok and type(res) == "string" and #res > 0 then return res end
    		end
    	end
    	return nil
    end
    
